"""Institutional phases, courts, grouped sovereign seats and regional events."""
import pathlib,json,urllib.parse
ROOT=pathlib.Path(__file__).resolve().parents[1];OUT=ROOT/'public/data';TAG='support-1400-0.22'
read=lambda f:json.loads((OUT/f).read_text(encoding='utf8'))
save=lambda f,d:(OUT/f).write_text(json.dumps(d,ensure_ascii=False,separators=(',',':'))+'\n',encoding='utf8',newline='\n')
wiki=lambda s:'https://en.wikipedia.org/wiki/'+urllib.parse.quote(s.replace(' ','_'))
def main():
 forms=read('governance.json');forms['records']=[v for v in forms['records'] if v.get('acquisition')!=TAG]
 def form(keys,a,b,tags,ref,note=''):
  forms['records'].append(dict(keys=keys.split('|'),start=a,end=b,tags=tags.split('|'),source=wiki(ref),sourceLabel='Forma institucional fechada · siglo XV',priority=15,note=note or 'Forma institucional; no una evaluación democrática ni una ideología deducida del color.',acquisition=TAG))
 for keys,tags,ref in [
  ('FRA|CASTILE|ARAGON|PRT|ENGLAND|SCOTLAND|NAVARRE-KINGDOM|POLAND-KINGDOM|NORWAY-KINGDOM|BOHEMIA|HUNGARY-KINGDOM','monarchy|kingdom','Late Middle Ages'),('KALMAR','monarchy|dynastic-union','Kalmar Union'),('MUSCOVY|LITHUANIA-DUCHY','monarchy|principality','Grand prince'),('HIST-Q12548','elective-monarchy|empire|feudal','Holy Roman Empire'),('SAXONY-ELECTORATE|ELECTORATE-BRANDENBURG','monarchy|electorate|feudal','Prince-elector'),('HESSE-UNITED','monarchy|principality|feudal','Landgraviate of Hesse'),('BAVARIA-DUCHY|BURGUNDY-DUCHY','monarchy|duchy|feudal','Duchy'),('SAVOY-COUNTY|URGELL-COUNTY','monarchy|feudal','Count'),('FLORENCE-REPUBLIC|HIST-Q4948|HIST-Q174306|HIST-Q208169','republic|oligarchy|city-state','Maritime republics'),('PAPAL-STATES','elective-monarchy|theocracy','Western Schism'),('CHE','confederal','Old Swiss Confederacy'),('MING','monarchy|empire','Ming dynasty'),('JOS|AYUTTHAYA','monarchy|kingdom','Late Middle Ages'),('JPN','monarchy|feudal','Ashikaga shogunate'),('TIMURID','monarchy|empire','Timurid Empire'),('OTT|MAMLUKS','monarchy|sultanate','Sultanate'),('ETH','monarchy|empire','Ethiopian Empire'),('HIST-Q796583','monarchy|kingdom','Kingdom of Kongo')]:form(keys,1400,1499,tags,ref)
 for keys,a,b,tags,ref in [
  ('BYZANTINE',1400,1453,'monarchy|empire','Byzantine Empire'),('TREBIZOND',1400,1461,'monarchy|empire','Empire of Trebizond'),('GRANADA-EMIRATE',1400,1492,'monarchy|sultanate','Emirate of Granada'),('MARINID',1400,1465,'monarchy|sultanate','Marinid Sultanate'),('WATTASID',1472,1499,'monarchy|sultanate','Wattasid dynasty'),('LODI',1451,1499,'monarchy|sultanate','Lodi dynasty'),('SAVOY-DUCHY',1416,1499,'monarchy|duchy|feudal','Duchy of Savoy'),('WURTTEMBERG-DUCHY',1495,1499,'monarchy|duchy|feudal','Duchy of Württemberg'),('AZTEC',1428,1499,'monarchy|empire','Aztec Empire'),('TENOCHTITLAN',1400,1499,'monarchy|city-state','Tenochtitlan'),('CUSCO-KINGDOM',1400,1437,'monarchy|kingdom','Kingdom of Cusco'),('INCA',1438,1499,'monarchy|empire','Inca Empire')]:form(keys,a,b,tags,ref)
 save('governance.json',forms)
 cs=read('identities.json')['countries'];places=read('historical-places.json');places['records']=[r for r in places['records'] if r.get('acquisition')!=TAG]
 def city(k,n,xy,a=1400,b=1499,grouped=False):
  v=dict(id='seat022-'+k+'-'+str(a),keys=[k],name=n,coordinates=xy,start=a,end=b,capital=True,role='Sede soberana · Estado agrupado' if grouped else 'Corte o capital histórica',source='https://www.wikidata.org/wiki/'+cs[k]['qid'],note='Sede de referencia, no perímetro ni frontera de control. No acredita presencia continua de la corte durante guerras,exilios o itinerancias.',acquisition=TAG)
  if grouped:v.update(aggregateKey='HIST-Q12548',entityName=cs[k]['name'],note='Sede de un Estado agrupado por la cartografía imperial. Abre su propia ficha sin inventar límites individuales ni atribuir al emperador toda su soberanía.')
  places['records'].append(v)
 for k,n,xy,a,b in [('HESSE-UNITED','Kassel · rama de Hesse',[9.4797,51.3127],1400,1499),('SAXONY-ELECTORATE','Wittenberg',[12.6484,51.8671],1400,1499),('ELECTORATE-BRANDENBURG','Berlín-Cölln',[13.405,52.52],1400,1499),('WURTTEMBERG-DUCHY','Stuttgart',[9.1829,48.7758],1495,1499)]:city(k,n,xy,a,b,True)
 for k,n,xy,a,b in [
  ('FRA','París · sede del reino',[2.3522,48.8566],1400,1499),('FRA','Bourges · cour de Charles VII',[2.3988,47.081],1422,1436),('CASTILE','Valladolid · corte itinerante',[-4.7286,41.6523],1400,1499),('ARAGON','Zaragoza · instituciones de Aragón',[-.8891,41.6488],1400,1499),('PRT','Lisboa',[-9.1393,38.7223],1400,1499),('ENGLAND','Londres',[-.1278,51.5074],1400,1499),('SCOTLAND','Edimburgo · sede regia',[-3.1883,55.9533],1400,1499),
  ('MUSCOVY','Moscú',[37.6173,55.7558],1400,1499),('BYZANTINE','Constantinopla',[28.9784,41.0082],1400,1453),('TREBIZOND','Trebisonda',[39.7168,41.0027],1400,1461),('OTT','Edirne',[26.5557,41.6771],1413,1452),('OTT','Constantinopla',[28.9784,41.0082],1453,1499),('GRANADA-EMIRATE','Granada',[-3.5986,37.1773],1400,1492),('NAVARRE-KINGDOM','Pamplona · instituciones',[-1.6458,42.8125],1400,1499),('BURGUNDY-DUCHY','Dijon',[5.0415,47.322],1400,1476),('POLAND-KINGDOM','Cracovia',[19.9445,50.0647],1400,1499),('LITHUANIA-DUCHY','Vilna',[25.2797,54.6872],1400,1499),
  ('MING','Nankín',[118.7969,32.0603],1400,1420),('MING','Pekín',[116.4074,39.9042],1421,1499),('JOS','Hanseong',[126.978,37.5665],1405,1499),('JPN','Kioto · corte y gobierno shogunal',[135.7681,35.0116],1400,1499),('TIMURID','Samarcanda',[66.9597,39.627],1400,1404),('TIMURID','Herat · rama de Jorasán',[62.2031,34.3529],1405,1499),('MAMLUKS','El Cairo',[31.2357,30.0444],1400,1499),('AZTEC','México-Tenochtitlan',[-99.1332,19.4326],1428,1499),('TENOCHTITLAN','México-Tenochtitlan',[-99.1332,19.4326],1400,1499),('CUSCO-KINGDOM','Cusco',[-71.9675,-13.5319],1400,1437),('INCA','Cusco',[-71.9675,-13.5319],1438,1499),('PAPAL-STATES','Roma',[12.4964,41.9028],1400,1499)]:city(k,n,xy,a,b)
 save('historical-places.json',places)
 context=read('historical-context.json');history=read('country-history.json');points=read('conflict-points.geojson')
 for data,field in [(context,'events'),(history,'records')]:data[field]=[v for v in data[field] if not v['id'].startswith('review022-')]
 points['features']=[v for v in points['features'] if not str(v['id']).startswith('review022-')]
 rows=[
  ('hundred','conflict','FRA|ENGLAND|BURGUNDY-DUCHY',1400,1453,'Guerra de los Cien Años · tramo observado','Pretensiones dinásticas,ocupaciones y alianzas cambiantes. El título francés de EnriqueVI no se utiliza como su reinado inglés ni acredita control de toda Francia. El conflicto comienza antes de1400.','Hundred Years War',[1,47]),
  ('roses','conflict','ENGLAND',1455,1487,'Guerras de las Dos Rosas','EnriqueVI y EduardoIV tienen restauraciones separadas; EduardoV,RicardoIII y EnriqueVII tienen ventanas propias. No se interpola un reinado continuo a través de una deposición.','Wars of the Roses',[-1.5,52]),
  ('ottoman','conflict','OTT|BYZANTINE|TIMURID',1402,1413,'Ankara e interregno otomano','La derrota deBayezidI abre una guerra de sucesión. Süleyman,Musa,İsa yMehmed tienen poderes regionales rivales, no un sultanato unificado durante todo el período.','Ottoman Interregnum',[32.85,39.93]),
  ('constantinople','conflict','BYZANTINE|OTT',1453,1453,'Caída de Constantinopla','La conquista de1453 termina el gobierno imperial deConstantinopla; Trebisonda y los poderes delPeloponeso tienen cronologías distintas. Un contorno residual posterior no prolonga automáticamente el mismo emperador.','Fall of Constantinople',[28.9784,41.0082]),
  ('trebizond','conflict','TREBIZOND|OTT',1461,1461,'Conquista de Trebisonda','La caída deTrebisonda de1461 se distingue deConstantinopla1453 y de la conquista deMorea. El marcador no reconstruye el frente de campaña.','Siege of Trebizond (1461)',[39.7168,41.0027]),
  ('granada','conflict','GRANADA-EMIRATE|CASTILE|ARAGON',1482,1492,'Guerra de Granada','Disputas nazaríes y conquista castellana. MuleyHacén yBoabdil tienen reinados interrumpidos y ámbitos rivales; la entrega deGranada ocurre el2deenerode1492.','Granada War',[-3.5986,37.1773]),
  ('kalmar','transition','KALMAR|SWE|NORWAY-KINGDOM|DNK',1400,1499,'Kalmar · unión y gobiernos separados','Las tres coronas tienen cronologías y regencias distintas. La fuente que usa elQIDdeMargaritaI para el antiguo reino noruego se corrige a la entidad política, sin convertir a una persona en un país.','Kalmar Union',None),
  ('burgundy','conflict','BURGUNDY-DUCHY|FRA|HIST-Q12548|CHE',1474,1482,'Guerras borgoñonas y sucesión','La muerte deCarloselTemerario en1477 abre disputas distintas sobre el ducado francés y otros dominios. María deBorgoña no controla automáticamente el ducado ocupado porFrancia.','Burgundian Wars',[6.5,47]),
  ('hussite','conflict','BOHEMIA|HIST-Q12548|HUNGARY-KINGDOM',1419,1434,'Guerras husitas','Múltiples facciones y pretensiones religiosas y políticas. Las soberanías y los frentes no se obtienen de una simple asignación de color a todaBohemia.','Hussite Wars',[14.4,50.08]),
  ('onin','conflict','JPN',1467,1477,'Guerra de Ōnin','La disputa shogunal y las alianzas regionales no equivalen a un enfrentamiento de dos países nacionales. El emperador y los shogunes conservan funciones distintas.','Ōnin War',[135.7681,35.0116]),
  ('ming','transition','MING',1400,1499,'Ming · capital y reinados interrumpidos','La capital pasa deNankín aPekín en1421. Yingzong tiene dos reinados, separados por el deJingtai tras la crisis deTumu. No se interpola un único mandato1435–1464.','Ming dynasty',None),
  ('aztec','transition','AZTEC|TENOCHTITLAN',1428,1499,'Triple Alianza · expansión y ciudades tributarias','Tenochtitlan,Texcoco yTlacopan forman una alianza desde1428. La autoridad mexica no implica soberanía nacional uniforme sobre cada ciudad; las fases anteriores no se convierten automáticamente en el imperio posterior.','Aztec Empire',None),
  ('inca','transition','INCA|CUSCO-KINGDOM',1438,1499,'Cusco y expansión inca · cronología debatida','Pachacuti,TúpacYupanqui yHuaynaCápac se ordenan conforme a una cronología tradicional. Las dataciones de las crónicas y la arqueología no son equivalentes a fechas de acceso absolutamente precisas.','Inca Empire',None),
  ('muscovy','conflict','MUSCOVY',1425,1453,'Moscovia · guerra de sucesión','BasilioII,Yuri,BasilioKosói yDmitriShemiaka representan sucesiones y pretensiones rivales. La continuidad de una pretensión no certifica un control efectivo ininterrumpido.','Muscovite War of Succession',[37.6173,55.7558]),
  ('schism','transition','PAPAL-STATES|SAVOY-DUCHY|FRA|HIST-Q12548',1400,1449,'Cisma occidental y obediencias pontificias','Los pontificados reconocidos,los concilios y los antipapas no se convierten en un único poder territorial uniforme. La serie de obediencias rivales y sus administraciones todavía es parcial.','Western Schism',None),
  ('iberian','transition','CASTILE|ARAGON|PRT|NAVARRE-KINGDOM',1410,1499,'Sucesiones ibéricas y unión dinástica','Compromiso deCaspe en1412,sucesión castellana y matrimonio deIsabel/Fernando no crean una administración nacional única. Cada corona conserva instituciones y símbolos propios.','Crown of Aragon',None)]
 for id,kind,keys,a,b,title,text,ref,xy in rows:
  e=dict(id='review022-'+id,type=kind,countries=keys.split('|'),title=title,start=f'{a}-01-01',end=f'{b+1}-01-01',text=text,source=wiki(ref),sourceLabel='Referencia documental · siglo XV',precision=9,startIsCoverageBoundary=True,endIsCoverageBoundary=True,note='Síntesis documental parcial; no geometría diaria de control.')
  if id=='constantinople':e['source']='https://www.metmuseum.org/essays/byzantium-ca-330-1453'
  if id=='inca':e['source']='https://www.cambridge.org/core/journals/radiocarbon/article/when-did-the-incas-build-machu-picchu-and-its-satellite-sites-new-approches-based-on-radiocarbon-dating/10254F52B68EAC0960DB85D91BB66593'
  context['events'].append(e);history['records'].append(dict(id=e['id'],keys=e['countries'],section='history' if kind=='conflict' else 'institutions',**{k:v for k,v in e.items() if k not in ['id','countries','type']}))
  if xy:points['features'].append(dict(type='Feature',id=e['id'],geometry=dict(type='Point',coordinates=xy),properties=dict(name=title,countries=e['countries'],kind='regional-conflict',start=e['start'],end=f'{b}-12-31',precision=9,source=e['source'],sourceLabel=e['sourceLabel'],note=text+' Punto regional; no superficie de ocupación.')))
 context['startYear']=1400;history['coverageStart']=1400;save('historical-context.json',context);save('country-history.json',history);save('conflict-points.geojson',points)
 print('New forms',sum(v.get('acquisition')==TAG for v in forms['records']),'new places',sum(v.get('acquisition')==TAG for v in places['records']),'new context',len(rows),'points',sum(v['id'].startswith('review022-') for v in points['features']))
if __name__=='__main__':main()
